parameters.jsCode:
const prev = $('1. Sub-Workflow Ingest Trigger').first().json;
const payload = prev.body ? prev.body : prev;
const aiResp = $input.first().json;

let aiResult = {};
if (aiResp && aiResp.candidates && aiResp.candidates[0]?.content?.parts?.[0]?.text) {
  try {
    aiResult = JSON.parse(aiResp.candidates[0].content.parts[0].text);
  } catch(e) {}
}

// Heuristic fallback nếu AI key chưa cấu hình hoặc mạng lỗi
if (!aiResult.category || !aiResult.priority) {
  const subject = (payload.subject || "").toLowerCase();
  const body = (payload.clean_body || payload.body || "").toLowerCase();
  const text = subject + " " + body;

  if (text.includes("sập") || text.includes("504") || text.includes("500") || text.includes("outage") || text.includes("down") || text.includes("khẩn cấp")) {
    aiResult = { department_code: "TECH", category: "Technical", priority: "P1 - Critical", sentiment: "Khan cap", urgency_reason: "Sự cố gián đoạn hạ tầng khẩn cấp", confidence_score: 0.98 };
  } else if (text.includes("lỗi") || text.includes("api") || text.includes("bug") || text.includes("database")) {
    aiResult = { department_code: "TECH", category: "Technical", priority: "P2 - High", sentiment: "Tieu cuc", urgency_reason: "Lỗi chức năng kỹ thuật", confidence_score: 0.92 };
  } else if (text.includes("báo giá") || text.includes("hợp đồng") || text.includes("bản quyền") || text.includes("tư vấn")) {
    aiResult = { department_code: "SALES", category: "Sales", priority: "P2 - High", sentiment: "Tich cuc", urgency_reason: "Yêu cầu kinh doanh & báo giá", confidence_score: 0.95 };
  } else if (text.includes("hóa đơn") || text.includes("vat") || text.includes("thanh toán") || text.includes("chứng từ")) {
    aiResult = { department_code: "FINANCE", category: "Finance", priority: "P3 - Medium", sentiment: "Trung tinh", urgency_reason: "Yêu cầu tài chính & hóa đơn", confidence_score: 0.94 };
  } else {
    aiResult = { department_code: "GENERAL", category: "General", priority: "P4 - Low", sentiment: "Trung tinh", urgency_reason: "Hỗ trợ chung tiêu chuẩn", confidence_score: 0.88 };
  }
}

return [{
  json: {
    ...payload,
    department_code: aiResult.department_code || "GENERAL",
    category: aiResult.category || "General",
    priority: aiResult.priority || "P3 - Medium",
    sentiment: aiResult.sentiment || "Trung tinh",
    confidence_score: aiResult.confidence_score || 0.95,
    urgency_reason: aiResult.urgency_reason || "Đã phân loại tự động bởi AI Agent 1"
  }
}];

const current = $('6. Compute Dynamic SLA Window Code').first().json;
return [{
  json: {
    sender_email: current.sender_email,
    sender_name: current.sender_name,
    subject: current.subject,
    title: current.subject,
    body: current.clean_body || current.body,
    category: current.category,
    department_code: current.department_code,
    priority: current.priority,
    sentiment: current.sentiment,
    urgency_reason: current.urgency_reason,
    sla_deadline: current.sla_deadline,
    confidence_score: current.confidence_score
  }
}];

const packet = $input.first().json;
const category = packet.category || "Technical";

// Bàn giao sang Luồng 3 nếu là sự cố kỹ thuật
if (category === "Technical" || packet.department_code === "TECH") {
  try {
    if (typeof this.helpers?.httpRequest === 'function') {
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'http://127.0.0.1:5678/webhook/m1-flow3-ticket',
        body: packet,
        json: true
      });
    } else {
      await fetch('http://127.0.0.1:5678/webhook/m1-flow3-ticket', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(packet)
      });
    }
  } catch(e) {
    // Luồng vẫn tiếp tục nếu web service đang bận
  }
}

return [{
  json: {
    status: "DISPATCHED",
    routed_department: category,
    department_code: packet.department_code,
    priority: packet.priority,
    downstream_handler: category === "Technical" ? "Flow 3 (Technical Ticket & SLA)" : 
                        category === "Sales" ? "Flow 7 (CRM Lead Qualification - Chờ TV3 triển khai)" :
                        category === "Finance" ? "Flow 9 (Invoice OCR - Chờ TV3 triển khai)" : "General Support Queue",
    payload: packet,
    completed_at: new Date().toISOString()
  }
}];
